package com.comandos.maintenance.service;
import com.comandos.audit.service.AuditService;import com.comandos.core.model.*;import com.comandos.custody.model.CustodyReturnItem;import com.comandos.inventory.model.*;import com.comandos.maintenance.dto.MaintenanceContract.*;import com.comandos.maintenance.model.*;import com.comandos.security.service.AccessPolicy;import jakarta.persistence.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service@Transactional(readOnly=true)public class MaintenanceService{
 private final EntityManager em;private final AccessPolicy access;private final AuditService audit;public MaintenanceService(EntityManager em,AccessPolicy access,AuditService audit){this.em=em;this.access=access;this.audit=audit;}
 @Transactional public PlanView plan(PlanRequest r){if(r==null||r.organizationId()==null||blank(r.name())||blank(r.type())||r.periodicityDays()==null||r.periodicityDays()<=0)bad("Organization, name, type and a positive periodicity are required.");access.requireScope("maintenance","CREATE",r.organizationId(),r.unitId());var o=locked(Organization.class,r.organizationId());var u=unit(o.id,r.unitId());var p=new MaintenancePlan();p.organization=o;p.unit=u;p.name=trim(r.name(),255,"Name");p.type=trim(r.type(),255,"Type");p.periodicityDays=r.periodicityDays();p.active=r.active()==null||r.active();em.persist(p);em.flush();var v=planView(p);audit.record("maintenance",p.id,"CREATE_PLAN",null,v);return v;}
 public Page<PlanView>plans(long org,Long unit){access.requireScope("maintenance","READ",org,unit);unit(org,unit);String w=" where p.organization.id=:o"+(unit==null?"":" and (p.unit is null or p.unit.id=:u)");var q=em.createQuery("select p from MaintenancePlan p"+w+" order by p.id",MaintenancePlan.class);var c=em.createQuery("select count(p) from MaintenancePlan p"+w,Long.class);q.setParameter("o",org);c.setParameter("o",org);if(unit!=null){q.setParameter("u",unit);c.setParameter("u",unit);}return new Page<>(q.getResultList().stream().map(this::planView).toList(),c.getSingleResult(),0,Integer.MAX_VALUE);}
 public Page<AssetOption>assets(long org,Long unit,String search){access.requireScope("maintenance","READ",org,unit);unit(org,unit);String w=" where a.location.organization.id=:o"+(unit==null?"":" and a.location.unit.id=:u")+" and a.status in ('AVAILABLE','BLOCKED') and not exists (select ri.id from ReservationItem ri where ri.asset.id=a.id and ri.reservation.status.code='ACTIVE') and not exists (select ci.id from InventoryCountItem ci where ci.asset.id=a.id and ci.inventoryCount.status.code='APPROVED' and ci.result.code='SHORTAGE') and (lower(a.assetCode) like :s or lower(a.model.name) like :s or lower(a.serialNumber) like :s)";var q=em.createQuery("select a from AssetItem a"+w+" order by a.id",AssetItem.class);var c=em.createQuery("select count(a) from AssetItem a"+w,Long.class);for(Query x:List.of(q,c)){x.setParameter("o",org).setParameter("s",term(search));if(unit!=null)x.setParameter("u",unit);}return new Page<>(q.setMaxResults(20).getResultList().stream().map(a->new AssetOption(a.id,a.assetCode,a.model.name,a.serialNumber,a.location.name)).toList(),c.getSingleResult(),0,20);}
 @Transactional public OrderView open(OpenRequest r){if(r==null||r.organizationId()==null||r.assetId()==null||blank(r.reason()))bad("Organization, asset and reason are required.");uuid(r.requestId());access.requireScope("maintenance","CREATE",r.organizationId(),r.unitId());lockCatalog();var o=locked(Organization.class,r.organizationId());if(!o.active)bad("Organization must be active.");var u=unit(o.id,r.unitId());String fp=hash(r.organizationId()+"|"+r.unitId()+"|"+r.planId()+"|"+r.assetId()+"|"+r.reason().trim()+"|"+r.custodyReturnItemId());var old=em.createQuery("select w from WorkOrder w where w.requestId=:r",WorkOrder.class).setParameter("r",r.requestId()).getResultStream().findFirst();if(old.isPresent()){if(!Objects.equals(old.get().maintenanceType,blank(r.maintenanceType())?"CORRECTIVE":r.maintenanceType().trim().toUpperCase(Locale.ROOT))||!Objects.equals(old.get().workshop,blank(r.workshop())?null:r.workshop().trim())||!Objects.equals(old.get().gunsmith,blank(r.gunsmith())?null:r.gunsmith().trim()))conflict("Request ID already used with different maintenance details.");access.requireEntity("maintenance","READ",old.get());if(!old.get().requestFingerprint.equals(fp)&&(r.custodyReturnItemId()!=null||!old.get().requestFingerprint.equals(hash(r.organizationId()+"|"+r.unitId()+"|"+r.planId()+"|"+r.assetId()+"|"+r.reason().trim()))))conflict("Request ID already used.");return view(old.get());}var a=locked(AssetItem.class,r.assetId());scope(a.location,o.id,r.unitId(),"CREATE");if(!Set.of("AVAILABLE","BLOCKED").contains(a.status))conflict("Asset is not eligible for maintenance.");if(count("select count(ri) from ReservationItem ri where ri.asset.id=:id and ri.reservation.status.code='ACTIVE'",a.id)>0)conflict("Reserved assets are not eligible for maintenance.");if(count("select count(ci) from InventoryCountItem ci where ci.asset.id=:id and ci.inventoryCount.status.code='APPROVED' and ci.result.code='SHORTAGE'",a.id)>0)conflict("Assets reported missing by inventory are not eligible for maintenance.");var source=maintenanceSource(r.custodyReturnItemId(),a,o.id,r.unitId());MaintenancePlan p=r.planId()==null?null:locked(MaintenancePlan.class,r.planId());if(p!=null&&(!p.active||!p.organization.id.equals(o.id)||p.unit!=null&&(u==null||!p.unit.id.equals(u.id))))bad("Maintenance plan does not belong to this scope.");var w=new WorkOrder();w.organization=o;w.unit=u;w.plan=p;w.asset=a;w.custodyReturnItem=source;w.organizationName=o.name;w.unitName=u==null?null:u.name;w.assetCode=a.assetCode;w.modelName=a.model.name;w.locationName=a.location.name;w.reason=trim(r.reason(),255,"Reason");w.maintenanceType=blank(r.maintenanceType())?"CORRECTIVE":trim(r.maintenanceType(),30,"Maintenance type").toUpperCase(Locale.ROOT);w.workshop=blank(r.workshop())?null:trim(r.workshop(),255,"Workshop");w.gunsmith=blank(r.gunsmith())?null:trim(r.gunsmith(),255,"Gunsmith");w.openedAt=LocalDateTime.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);w.sentAt=w.openedAt;var actor=audit.actor();w.openedById=actor.id();w.openedByLogin=actor.login();w.requestId=r.requestId();w.requestFingerprint=fp;var m=movement(a,a.location,"MAINTENANCE_ISSUE",BigDecimal.ONE.negate(),w.openedAt);w.issueMovement=m;em.persist(w);a.status="IN_MAINTENANCE";em.flush();var v=view(w);audit.record("maintenance",w.id,"OPEN",null,v);return v;}
 @Transactional public OrderView complete(long id,CompleteRequest r){if(r==null||blank(r.defect())||blank(r.cause())||blank(r.opinion())||blank(r.testResult())||blank(r.testNotes())||r.services()==null||r.services().isEmpty())bad("Diagnosis, services and functional test are required.");uuid(r.requestId());if(r.nextMaintenanceDays()!=null&&r.nextMaintenanceDays()<=0)bad("Next maintenance days must be positive.");if(!Set.of("APPROVED","REJECTED").contains(r.testResult()))bad("Test result must be APPROVED or REJECTED.");var w=locked(WorkOrder.class,id);access.requireEntity("maintenance","COMPLETE",w);String fp=completionFingerprint(r);if("COMPLETED".equals(w.status)){if(!Objects.equals(w.completionRequestId,r.requestId())||!Objects.equals(w.completionFingerprint,fp))conflict("Work order is already completed.");return view(w);}locked(AssetItem.class,w.asset.id);if(!"IN_MAINTENANCE".equals(w.asset.status))conflict("Asset is no longer in maintenance.");var before=view(w);var d=new Diagnosis();d.workOrder=w;d.defect=trim(r.defect(),255,"Defect");d.cause=trim(r.cause(),255,"Cause");d.opinion=trim(r.opinion(),1000,"Opinion");em.persist(d);BigDecimal totalCost=BigDecimal.ZERO;for(var s:r.services()){if(s==null||blank(s.description())||s.cost()==null||s.cost().signum()<0)bad("Every service requires a description and non-negative cost.");var e=new ExecutedService();e.workOrder=w;e.description=trim(s.description(),1000,"Service description");e.cost=s.cost();em.persist(e);totalCost=totalCost.add(s.cost());}if(r.parts()!=null)for(var part:r.parts()){if(part==null||blank(part.description())||part.quantity()==null||part.quantity().signum()<=0||part.unitCost()==null||part.unitCost().signum()<0)bad("Every part requires description, positive quantity and non-negative unit cost.");var mp=new MaintenancePart();mp.workOrder=w;mp.description=trim(part.description(),255,"Part");mp.quantity=part.quantity();mp.unitCost=part.unitCost();mp.partNumber=blank(part.partNumber())?null:trim(part.partNumber(),255,"Part number");em.persist(mp);totalCost=totalCost.add(part.quantity().multiply(part.unitCost()));}w.totalCost=totalCost;
 var t=new FunctionalTest();t.workOrder=w;t.testedAt=LocalDateTime.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);t.result=r.testResult();t.notes=trim(r.testNotes(),1000,"Test notes");em.persist(t);w.completedAt=t.testedAt;w.returnedAt=t.testedAt;Integer nextDays=r.nextMaintenanceDays()!=null?r.nextMaintenanceDays():w.plan==null?null:w.plan.periodicityDays;w.nextMaintenanceAt=nextDays==null?null:t.testedAt.plusDays(nextDays);w.status="COMPLETED";w.completionRequestId=r.requestId();w.completionFingerprint=fp;var actor=audit.actor();w.completedById=actor.id();w.completedByLogin=actor.login();w.asset.status="APPROVED".equals(t.result)&&(w.asset.validUntil==null||!w.asset.validUntil.isBefore(LocalDate.now()))?"AVAILABLE":"BLOCKED";w.returnMovement=movement(w.asset,w.asset.location,"MAINTENANCE_RETURN",BigDecimal.ONE,w.completedAt);em.flush();var v=view(w);audit.record("maintenance",w.id,"COMPLETE",before,v);return v;}
 public Page<OrderView>orders(long org,Long unit,int page){access.requireScope("maintenance","READ",org,unit);unit(org,unit);if(page<0)bad("Invalid page.");String w=" where w.organization.id=:o"+(unit==null?"":" and w.unit.id=:u");var q=em.createQuery("select w from WorkOrder w"+w+" order by w.id desc",WorkOrder.class);var c=em.createQuery("select count(w) from WorkOrder w"+w,Long.class);q.setParameter("o",org);c.setParameter("o",org);if(unit!=null){q.setParameter("u",unit);c.setParameter("u",unit);}return new Page<>(q.setFirstResult(page*20).setMaxResults(20).getResultList().stream().map(this::view).toList(),c.getSingleResult(),page,20);}
 private OrderView view(WorkOrder w){var d=em.createQuery("select d from Diagnosis d where d.workOrder.id=:id",Diagnosis.class).setParameter("id",w.id).getResultStream().findFirst();var ss=em.createQuery("select s from ExecutedService s where s.workOrder.id=:id order by s.id",ExecutedService.class).setParameter("id",w.id).getResultList().stream().map(s->new ServiceView(s.description,decimal(s.cost))).toList();var t=em.createQuery("select t from FunctionalTest t where t.workOrder.id=:id order by t.id desc",FunctionalTest.class).setParameter("id",w.id).setMaxResults(1).getResultStream().findFirst();return new OrderView(w.id,w.organization.id,w.organizationName,w.unit==null?null:w.unit.id,w.unitName,w.plan==null?null:w.plan.id,w.plan==null?null:w.plan.name,w.asset.id,w.assetCode,w.modelName,w.locationName,w.reason,w.status,w.openedAt.toString(),w.completedAt==null?null:w.completedAt.toString(),w.openedByLogin,w.completedByLogin,d.map(x->x.defect).orElse(null),d.map(x->x.cause).orElse(null),d.map(x->x.opinion).orElse(null),ss,t.map(x->x.result).orElse(null),t.map(x->x.notes).orElse(null),w.custodyReturnItem==null?null:w.custodyReturnItem.id,w.maintenanceType,w.workshop,w.gunsmith,w.nextMaintenanceAt==null?null:w.nextMaintenanceAt.toString(),decimal(w.totalCost),em.createQuery("select p from MaintenancePart p where p.workOrder.id=:id order by p.id",MaintenancePart.class).setParameter("id",w.id).getResultList().stream().map(p->new PartView(p.description,decimal(p.quantity),decimal(p.unitCost),p.partNumber)).toList());}
 private CustodyReturnItem maintenanceSource(Long id,AssetItem asset,long organizationId,Long unitId){if(id==null)return null;var source=locked(CustodyReturnItem.class,id);var item=source.custodyItem;if(item.asset==null||!item.asset.id.equals(asset.id))bad("Custody return item does not belong to the selected asset.");if(source.conditionType==null||!source.conditionType.blocksAvailability)conflict("Only a blocking custody return inspection can originate maintenance.");var custody=item.custody;if(!custody.organization.id.equals(organizationId)||!Objects.equals(custody.unit==null?null:custody.unit.id,unitId))bad("Custody return item does not belong to the selected scope.");if(count("select count(w) from WorkOrder w where w.custodyReturnItem.id=:id",id)>0)conflict("A work order already exists for this custody return item.");return source;}
 private PlanView planView(MaintenancePlan p){return new PlanView(p.id,p.organization.id,p.unit==null?null:p.unit.id,p.name,p.type,p.periodicityDays,p.active);}
 private StockMovement movement(AssetItem a,StockLocation l,String n,BigDecimal q,LocalDateTime at){var m=new StockMovement();m.asset=a;m.location=l;m.nature=n;m.quantity=q;m.movedAt=at;m.operatorLogin=audit.actor().login();m.operatorId=audit.actor().id();em.persist(m);return m;}
 private void scope(StockLocation l,long o,Long u,String action){access.requireScope("maintenance",action,l.organization.id,l.unit==null?null:l.unit.id);if(!l.organization.id.equals(o)||u!=null&&(l.unit==null||!l.unit.id.equals(u)))bad("Asset does not belong to the selected scope.");}
 private OrganizationalUnit unit(long o,Long id){if(id==null)return null;var u=em.find(OrganizationalUnit.class,id);if(u==null||!u.organization.id.equals(o))bad("Select a unit in the organization.");if(!Boolean.TRUE.equals(u.active))bad("Selected unit must be active.");return u;}private long count(String q,long id){return em.createQuery(q,Long.class).setParameter("id",id).getSingleResult();}private void lockCatalog(){em.createQuery("select c from ItemCategory c order by c.id",ItemCategory.class).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultList();}private<T>T locked(Class<T>c,Long id){var x=id==null?null:em.createQuery("select e from "+c.getSimpleName()+" e where e.id=:id",c).setParameter("id",id).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultStream().findFirst().orElse(null);if(x==null)bad(c.getSimpleName()+" not found.");return x;}
 private static String completionFingerprint(CompleteRequest r){return hash(r.defect()+"|"+r.cause()+"|"+r.opinion()+"|"+r.services()+"|"+r.testResult()+"|"+r.testNotes()+(r.parts()==null&&r.nextMaintenanceDays()==null?"":"|"+r.parts()+"|"+r.nextMaintenanceDays()));}private static String trim(String s,int n,String l){s=s.trim();if(s.length()>n)bad(l+" is too long.");return s;}private static boolean blank(String s){return s==null||s.isBlank();}private static String term(String s){return"%"+(s==null?"":s.trim().toLowerCase(Locale.ROOT)).replace("%","!%").replace("_","!_")+"%";}private static String decimal(BigDecimal v){return v.setScale(4,RoundingMode.UNNECESSARY).toPlainString();}private static void uuid(String v){try{if(v==null||!UUID.fromString(v).toString().equals(v))throw new Exception();}catch(Exception e){bad("A canonical UUID request ID is required.");}}private static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
}

